// ── Equipment List ────────────────────────────────────────────────────────────
const EQUIPMENT_SECTIONS = [
    'BMH','Receiving','Junction House','Lorry Loading',
    'Silo 1','Silo 2','Silo 3',
    'Switchrooms','Shipping Spouts','Dust Plants',
    'Basement-Receiving','Workshop','Control Room','PLC and Comms',
];

function loadEquipment() {
    allEquipment = DATA_EQUIPMENT;
    equipAttrs   = {};
    (DATA_ATTRS || []).forEach(entry => { equipAttrs[entry.equipment_id] = entry.attributes; });
    equipRelations = DATA_RELATIONS || [];
    renderEquipmentList();
}

function renderEquipmentList() {
    const container = el('equipment-list-container');
    if (!container) return;
    const byArea = {};
    allEquipment.forEach(item => {
        const area = item.area || 'Other';
        if (!byArea[area]) byArea[area] = [];
        byArea[area].push(item);
    });
    container.innerHTML = EQUIPMENT_SECTIONS.map(section => {
        const equipList = byArea[section] || [];
        const body = equipList.length > 0
            ? `<table class="data-table"><thead><tr><th>Equipment</th><th>Type</th><th>MCC</th><th>Specs</th></tr></thead><tbody>
                ${equipList.map(e => {
                    const hasAttrs = equipAttrs[e.id] && equipAttrs[e.id].length > 0;
                    return `<tr class="equip-row" data-id="${e.id}">
                        <td class="equip-name-cell">
                            <span class="equip-name-link">${e.name}</span>
                            ${e.long_name && e.long_name !== e.name ? `<span class="equip-mfr">${e.long_name}</span>` : ''}
                            ${e.manufacturer ? `<span class="equip-mfr">${e.manufacturer}</span>` : ''}
                        </td>
                        <td>${formatEquipType(e.type)}</td>
                        <td>${e.mcc ? `<span class="mcc-badge">${e.mcc}</span>` : '—'}</td>
                        <td>${hasAttrs ? `<span class="has-specs">● Specs</span>` : `<span class="no-specs">No data yet</span>`}</td>
                    </tr>`;
                }).join('')}
               </tbody></table>`
            : `<p class="card-note">No equipment recorded yet.</p>`;
        return `<div class="content-card"><h3>${section}</h3>${body}</div>`;
    }).join('');
    container.querySelectorAll('.equip-row').forEach(row => {
        row.addEventListener('click', () => showEquipmentDetail(parseInt(row.dataset.id)));
    });
}

function formatEquipType(type) {
    const map = {
        belt_conveyor:'Belt Conveyor', chain_conveyor:'Chain Conveyor',
        bucket_elevator:'Bucket Elevator', dust_filter:'Dust Filter / Fan',
        rotary_valve:'Rotary Valve', tripper:'Tripper',
        control_panel:'Control Panel', junction_box:'Junction Box',
        ship_unloader:'Ship Unloader', dust_control:'Dust Control',
        compressor:'Compressor', magnetic_separator:'Magnetic Separator',
        substation:'Substation', garner:'Garner', turnhead:'Turnhead',
        bin:'Bin', bin_group:'Bin Group', hopper:'Hopper',
        external_interface:'External Interface', room:'Room',
        process_equipment:'Process Equipment',
    };
    return map[type] || type || '—';
}

// ── Equipment Detail Panel ────────────────────────────────────────────────────
function navigateToEquipment(id) {
    document.querySelector('.nav-item[href="#equipment"]')?.click();
    showView('equip-list');
    setTimeout(() => showEquipmentDetail(id), 50);
}

function showEquipmentDetail(id) {
    const equip = allEquipment.find(e => e.id === id);
    if (!equip) return;
    const attrs    = equipAttrs[id] || [];
    const rels     = equipRelations.filter(r => r.parent_id === id || r.child_id === id);
    const drawings = allDrawings.filter(d => (equip.drawing_refs || []).includes(d.drawing_ref));
    const linkedDocs = (DATA_DOCUMENTS || []).filter(d => (d.equipment_ids || []).includes(id));
    const lubeLinks = (DATA_EQUIPMENT_LUBRICANTS || []).filter(link => link.equipment_id === id);
    const pulleyLinks = (DATA_EQUIPMENT_PULLEYS || []).filter(link => link.equipment_id === id);
    const gearboxLinks = (DATA_EQUIPMENT_GEARBOXES || []).filter(link => link.equipment_id === id);
    const motorLinks = (DATA_ELECTRICAL_MOTORS || []).filter(link => link.equipment_id === id);
    const dustBagLinks = (DATA_EQUIPMENT_DUST_BAGS || []).filter(link => link.equipment_id === id);
    const dustBagHistory = (DATA_DUST_BAG_CHANGE_HISTORY || []).filter(link => link.equipment_id === id);
    const sources  = gatherSourcesForEquipment(equip, drawings);
    let html = `<div class="detail-header">
        <div>
            <div class="detail-name">${equip.name}</div>
            <div class="detail-meta">
                ${equip.long_name && equip.long_name !== equip.name ? `<span>${equip.long_name}</span>` : ''}
                ${equip.area ? `<span>${equip.area}</span>` : ''}
                ${equip.mcc  ? `<span class="mcc-badge">${equip.mcc}</span>` : ''}
                ${equip.manufacturer ? `<span>${equip.manufacturer}${equip.model ? ' — '+equip.model : ''}</span>` : ''}
            </div>
            ${equip.source_document ? `<div class="record-source">Source: ${escHtml(equip.source_document)}</div>` : ''}
        </div>
        <button class="detail-close" onclick="closeEquipmentDetail()">✕</button>
    </div>`;
    if (attrs.length > 0) {
        const catLabels = { motor:'Motor', gearbox:'Gearbox', drive:'Drive',
            fluid_coupling:'Fluid Coupling', belt:'Belt', roller:'Rollers',
            bearing:'Bearings', coupling:'Coupling', general:'General', plc:'PLC / Control' };
        const categories = [...new Set(attrs.map(a => a.category))];
        html += `<div class="detail-section"><h4>Specifications</h4>`;
        categories.forEach(cat => {
            const catAttrs = attrs.filter(a => a.category === cat);
            html += `<div class="detail-attr-group"><div class="detail-attr-group-label">${catLabels[cat] || cat}</div>`;
            catAttrs.forEach(a => {
                const val  = a.unit ? `${a.value} ${a.unit}` : a.value;
                const conf = a.confidence !== 'VERIFIED' ? `<span class="conf-badge conf-${a.confidence.toLowerCase()}">${a.confidence}</span>` : '';
                const srcLabel = a.source_document || a.source || '';
                const src  = srcLabel ? `<span class="attr-source" title="${escHtml(a.source || '')}">${escHtml(srcLabel)}</span>` : '';
                html += `<div class="detail-attr-row">
                    <span class="attr-key">${formatAttrKey(a.key)}</span>
                    <span class="attr-val">${val} ${conf} ${src}</span>
                </div>`;
            });
            html += `</div>`;
        });
        html += `</div>`;
    } else {
        html += `<div class="detail-section detail-empty"><p>No specifications recorded yet.</p>
            <p>Drop files into the Incoming folder and tell Gary what they are.</p></div>`;
    }
    if (drawings.length > 0) {
        html += `<div class="detail-section"><h4>Linked Drawings</h4>`;
        drawings.forEach(d => {
            html += `<div class="detail-drawing-row">
                <span class="detail-drawing-ref" onclick="jumpToDrawing('${d.drawing_ref}')" title="Find in Schematics">${d.drawing_ref||'—'}</span>
                <span class="detail-drawing-desc">${d.description||d.filename}</span>
                <span class="detail-drawing-mcc">${d.mcc||''}</span>
                ${d.pdf_link ? `<a class="detail-source-link" href="${d.pdf_link}" target="_blank" rel="noopener">Open source</a>` : ''}
            </div>`;
        });
        html += `</div>`;
    } else if (equip.drawing_refs && equip.drawing_refs.length > 0) {
        html += `<div class="detail-section"><h4>Drawing References</h4>`;
        equip.drawing_refs.forEach(ref => {
            html += `<div class="detail-drawing-row">
                <span class="detail-drawing-ref" onclick="jumpToDrawing('${ref}')" title="Find in Schematics">${ref}</span>
                <span class="detail-drawing-desc detail-empty-small">(not yet linked)</span>
            </div>`;
        });
        html += `</div>`;
    }
    if (linkedDocs.length > 0) {
        html += `<div class="detail-section"><h4>Linked Documents</h4>`;
        linkedDocs.forEach(d => {
            html += `<div class="detail-drawing-row">
                <span class="detail-drawing-ref">${d.category || 'document'}</span>
                <span class="detail-drawing-desc">${d.description || d.filename}</span>
                <span class="detail-drawing-mcc">${d.area || ''}</span>
                ${d.pdf_link ? `<a class="detail-source-link" href="${d.pdf_link}" target="_blank" rel="noopener">Open source</a>` : ''}
            </div>`;
        });
        html += `</div>`;
    }
    if (rels.length > 0) {
        html += `<div class="detail-section"><h4>Related Equipment</h4>`;
        rels.forEach(r => {
            const isParent = r.parent_id === id;
            const otherId  = isParent ? r.child_id  : r.parent_id;
            const otherNm  = isParent ? r.child_name : r.parent_name;
            html += `<div class="detail-rel-row">
                <span class="detail-rel-type">${isParent ? r.type : '← '+r.type}</span>
                <span class="detail-rel-name equip-tag" onclick="navigateToEquipment(${otherId})">${otherNm}</span>
            </div>`;
        });
        html += `</div>`;
    }
    if (lubeLinks.length > 0) {
        html += `<div class="detail-section"><h4>Lubricants</h4>`;
        lubeLinks.forEach(link => {
            html += `<div class="lubricant-detail-row">
                <span class="lubricant-detail-product">${link.product_description}</span>
                <span class="lubricant-detail-component">${link.component || 'Lubrication point'}</span>
                <span class="lubricant-detail-application">${link.application || link.source_equipment_label}</span>
            </div>`;
        });
        html += `</div>`;
    }
    if (pulleyLinks.length > 0) {
        html += `<div class="detail-section"><h4>Pulleys</h4>`;
        pulleyLinks.forEach(link => {
            html += `<div class="pulley-detail-row">
                <span class="pulley-detail-name">${link.pulley_label}</span>
                <span>${link.pulley_diameter || '—'}</span>
                <span>${link.face_width || '—'}</span>
                <span>${link.shaft_diameter || '—'}</span>
                <span>${link.bearing_details || '—'}</span>
            </div>`;
        });
        html += `</div>`;
    }
    if (gearboxLinks.length > 0) {
        html += `<div class="detail-section"><h4>Gearboxes</h4>`;
        gearboxLinks.forEach(link => {
            html += `<div class="gearbox-detail-row">
                <span class="gearbox-detail-name">${link.gearbox_label || 'Gearbox'}</span>
                <span>${link.oil_product || 'Oil to confirm'}</span>
                <span>${link.oil_supplier || '—'}</span>
                <span>${link.gearbox_make || '—'}</span>
                <span>${link.gearbox_type || '—'}</span>
                <span>${link.gearbox_reduction || link.gearbox_output_speed || '—'}</span>
            </div>`;
        });
        html += `</div>`;
    }
    if (motorLinks.length > 0) {
        html += `<div class="detail-section"><h4>Motors</h4>`;
        motorLinks.forEach(link => {
            html += `<div class="motor-detail-row">
                <span class="motor-detail-name">${link.plant_label}</span>
                <span>${link.make || '—'}</span>
                <span>${link.motor_type || '—'}</span>
                <span>${link.kilowatts ? `${link.kilowatts} kW` : '—'}</span>
                <span>${link.volts || '—'}</span>
                <span>${link.serial_number || '—'}</span>
            </div>`;
        });
        html += `</div>`;
    }
    if (dustBagLinks.length > 0 || dustBagHistory.length > 0) {
        html += `<div class="detail-section"><h4>Dust Bags</h4>`;
        dustBagLinks.forEach(link => {
            html += `<div class="dust-detail-row">
                <span class="dust-detail-name">${link.application_label}</span>
                <span>${link.bag_type || '—'}</span>
                <span>${link.quantity_required || '—'}</span>
                <span>${link.total_required || '—'}</span>
                <span>Stock placeholder</span>
            </div>`;
        });
        if (dustBagHistory.length > 0) {
            const latest = dustBagHistory.slice(-6);
            html += `<div class="dust-history-list">`;
            latest.forEach(entry => {
                html += `<span class="dust-history-pill">${entry.year_label}: ${entry.change_date}</span>`;
            });
            html += `</div>`;
        }
        html += `</div>`;
    }
    if (equip.notes) {
        html += `<div class="detail-section"><h4>Notes</h4><p class="detail-notes">${equip.notes}</p></div>`;
    }
    html += buildSourceListHtml(sources);
    html += `<div class="detail-section">
        <h4>Verification</h4>
        <p class="detail-note">Check the original file before relying on this record.</p>
        ${renderFeedbackPanel({
            item_type: 'equipment',
            item_id: String(equip.id),
            item_label: equip.name,
            response_text: `${equip.name} (${equip.area || 'Unknown area'})`,
            sources,
            channel: 'portal',
        })}
    </div>`;
    el('detail-content').innerHTML = html;
    el('equipment-detail-panel').classList.add('panel-open');
    el('detail-overlay').style.display = 'block';
}

function closeEquipmentDetail() {
    el('equipment-detail-panel').classList.remove('panel-open');
    el('detail-overlay').style.display = 'none';
}

function formatAttrKey(key) {
    return key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

function jumpToDrawing(ref) {
    closeEquipmentDetail();
    document.querySelector('.nav-item[href="#schematics"]')?.click();
    setTimeout(() => {
        const input = el('schematics-search');
        if (input) { input.value = ref; renderDrawings(); }
    }, 50);
}

// ── Site Layout Drill-Down ────────────────────────────────────────────────────
const TYPE_LABELS = {
    belt_conveyor:'Belt Conveyor', chain_conveyor:'Chain Conveyor',
    bucket_elevator:'Bucket Elevator', dust_control:'Dust Control Unit',
    compressor:'Compressor', magnetic_separator:'Magnetic Separator',
    rotary_valve:'Rotary Valve', ship_unloader:'Ship Unloader',
    substation:'Substation', garner:'Garner', turnhead:'Turnhead',
    bin:'Bin', bin_group:'Bin Group', hopper:'Hopper',
    external_interface:'External Interface', room:'Room',
    process_equipment:'Process Equipment',
};
const CAT_META = {
    electrical:   { label:'Electrical',    colour:'#4299e1' },
    mechanical:   { label:'Mechanical',    colour:'#ed8936' },
    dust_control: { label:'Dust Control',  colour:'#68d391' },
    info_required:{ label:'Info Required', colour:'#fc8181' },
    process:      { label:'Process',       colour:'#9f7aea' },
    safety:       { label:'Safety',        colour:'#f56565' },
    general:      { label:'General',       colour:'#a0aec0' },
};

const SCHEMATIC_FLOW = [
    ['receiving'],
    ['main_elevator_and_distribution'],
    ['silo_cluster_1', 'silo_cluster_2', 'silo_3', 'mill_feed'],
    ['weighback_and_lorry_intake', 'dust_plant_and_discharge'],
    ['lorry_loading', 'external_interfaces'],
];

function loadSiteLayout() {
    siteLayout = DATA_LAYOUT;
    renderLocationCards();
}

function getComponentCount(asset) {
    return (asset.components || []).length;
}

function getAssetCategoryCounts(asset) {
    return (asset.components || []).reduce((counts, component) => {
        const category = component.category || 'general';
        counts[category] = (counts[category] || 0) + 1;
        return counts;
    }, {});
}

function buildComponentPills(asset) {
    const counts = getAssetCategoryCounts(asset);
    return Object.keys(CAT_META).map(category => {
        const count = counts[category] || 0;
        if (!count) return '';
        return `<span class="comp-pill pill-${category.replace('_', '-')}">${count} ${CAT_META[category].label}</span>`;
    }).filter(Boolean).join('');
}

function renderProcessSchematic() {
    if (!siteLayout) siteLayout = DATA_LAYOUT;
    const map = el('schematic-map');
    if (!map || !siteLayout) return;
    const locationsById = new Map(siteLayout.locations.map(location => [location.id, location]));
    map.innerHTML = SCHEMATIC_FLOW.map((column, index) => `
        <div class="schematic-column">
            ${column.map(locationId => {
                const location = locationsById.get(locationId);
                if (!location) return '';
                const assetCount = location.assets.length;
                const componentCount = location.assets.reduce((sum, asset) => sum + getComponentCount(asset), 0);
                return `<button class="schematic-node" data-location-id="${location.id}">
                    <span class="schematic-node-title">${location.name}</span>
                    <span class="schematic-node-meta">${assetCount} assets · ${componentCount} points</span>
                </button>`;
            }).join('')}
            ${index < SCHEMATIC_FLOW.length - 1 ? '<div class="schematic-flow-arrow">&#8594;</div>' : ''}
        </div>
    `).join('');
    map.querySelectorAll('.schematic-node').forEach(node => {
        node.addEventListener('click', () => selectSchematicLocation(node.dataset.locationId));
    });
    selectSchematicLocation(activeSchematicLocation?.id || 'receiving');
}

function selectSchematicLocation(locationId) {
    if (!siteLayout) return;
    activeSchematicLocation = siteLayout.locations.find(location => location.id === locationId);
    if (!activeSchematicLocation) return;
    document.querySelectorAll('.schematic-node').forEach(node => {
        node.classList.toggle('active', node.dataset.locationId === locationId);
    });
    const summary = el('schematic-stage-summary');
    const list = el('schematic-asset-list');
    if (!summary || !list) return;
    const assetCount = activeSchematicLocation.assets.length;
    const componentCount = activeSchematicLocation.assets.reduce((sum, asset) => sum + getComponentCount(asset), 0);
    summary.innerHTML = `
        <div class="schematic-stage-kicker">Selected Stage</div>
        <h3>${activeSchematicLocation.name}</h3>
        <div class="schematic-stage-metrics">
            <span>${assetCount} assets</span>
            <span>${componentCount} component points</span>
        </div>`;
    list.innerHTML = activeSchematicLocation.assets.map(asset => `
        <button class="schematic-asset-row" data-asset-id="${asset.id}">
            <span>
                <strong>${asset.name}</strong>
                <small>${asset.long_name || TYPE_LABELS[asset.type] || asset.type || ''}</small>
            </span>
            <span class="schematic-asset-type">${TYPE_LABELS[asset.type] || asset.type || ''}</span>
            <span class="schematic-asset-pills">${buildComponentPills(asset)}</span>
        </button>
    `).join('');
    list.querySelectorAll('.schematic-asset-row').forEach(row => {
        row.addEventListener('click', () => showSchematicAssetDetail(row.dataset.assetId));
    });
}

function showSchematicAssetDetail(assetId) {
    if (!activeSchematicLocation) return;
    activeLocation = activeSchematicLocation;
    showAssetDetail(assetId);
}

function showView(view) {
    const isLayout = view === 'site-layout';
    el('site-layout-view').style.display = isLayout ? '' : 'none';
    el('equip-list-view').style.display  = isLayout ? 'none' : '';
    el('btn-site-layout').classList.toggle('active', isLayout);
    el('btn-equip-list').classList.toggle('active', !isLayout);
}

function renderLocationCards() {
    el('asset-list-view').style.display   = 'none';
    el('location-cards').style.display    = '';
    el('location-breadcrumb').style.display = 'none';
    el('location-cards').innerHTML = siteLayout.locations.map(loc => {
        const assetCount = loc.assets.length;
        const compCount  = loc.assets.reduce((n, a) => n + getComponentCount(a), 0);
        return `<div class="loc-card" onclick="openLocation('${loc.id}')">
            <div class="loc-card-name">${loc.name}</div>
            <div class="loc-card-stats">
                <span>${assetCount} asset${assetCount !== 1 ? 's' : ''}</span>
                <span>${compCount} components</span>
            </div>
            <div class="loc-card-arrow">&#8594;</div>
        </div>`;
    }).join('');
}

function openLocation(locId) {
    activeLocation = siteLayout.locations.find(l => l.id === locId);
    if (!activeLocation) return;
    el('location-cards').style.display   = 'none';
    el('asset-list-view').style.display  = '';
    const bc = el('location-breadcrumb');
    bc.style.display = '';
    bc.innerHTML = `<span class="bc-link" onclick="renderLocationCards()">&#8592; All Locations</span>
                    <span class="bc-sep">›</span>
                    <span class="bc-current">${activeLocation.name}</span>`;
    el('asset-cards').innerHTML = activeLocation.assets.map(asset => {
        const pills = buildComponentPills(asset);
        return `<div class="asset-card" onclick="showAssetDetail('${asset.id}')">
            <div class="asset-card-name">${asset.name}</div>
            <div class="asset-card-type">${TYPE_LABELS[asset.type] || asset.type || ''}</div>
            <div class="asset-card-pills">${pills}</div>
            <div class="asset-card-count">${getComponentCount(asset)} components &#8594;</div>
        </div>`;
    }).join('');
}

function showAssetDetail(assetId) {
    if (!activeLocation) return;
    const asset = activeLocation.assets.find(a => a.id === assetId);
    if (!asset) return;
    const hasComponentSpecs = (asset.components || []).some(component => component.spec);
    const groups = {};
    (asset.components || []).forEach(c => {
        const cat = c.category || 'general';
        if (!groups[cat]) groups[cat] = [];
        groups[cat].push(c);
    });
    let html = `<div class="detail-header">
        <div>
            <div class="detail-name">${asset.name}</div>
            <div class="detail-meta">
                <span>${activeLocation.name}</span>
                <span class="type-badge">${TYPE_LABELS[asset.type] || asset.type || ''}</span>
            </div>
            ${asset.notes ? `<div class="detail-location">${asset.notes}</div>` : ''}
        </div>
        <button class="detail-close" onclick="closeEquipmentDetail()">✕</button>
    </div>
    <div class="detail-section">
        <h4>Components</h4>
        <p class="detail-note">${hasComponentSpecs ? 'Known values shown where available. Other fields awaiting data.' : 'All fields awaiting data.'} Source: site layout register — 20 Apr 2026.</p>`;
    Object.keys(CAT_META).forEach(cat => {
        const comps = groups[cat];
        if (!comps || comps.length === 0) return;
        const meta = CAT_META[cat];
        html += `<div class="comp-group">
            <div class="comp-group-label" style="border-left:4px solid ${meta.colour};padding-left:8px;color:${meta.colour};font-weight:600;margin:12px 0 6px;">${meta.label}</div>`;
        comps.forEach(c => {
            const specHtml = c.spec
                ? `<span class="comp-spec" title="Source: ${c.spec_source || 'site records'}">${c.spec}</span>`
                : `<span class="comp-status awaiting">Awaiting data</span>`;
            html += `<div class="comp-row">
                <span class="comp-name">${c.name}</span>
                ${specHtml}
            </div>`;
        });
        html += `</div>`;
    });
    html += `</div>`;
    const assetTerms = [
        asset.id,
        asset.name,
        asset.canonical_name,
        asset.long_name,
        ...(asset.legacy_name_aliases || []),
    ].filter(Boolean).map(t => String(t).toUpperCase());
    const matched = allEquipment.filter(e => {
        const equipmentTerms = [
            e.name,
            ...(e.aliases || []).map(alias => alias.name),
        ].filter(Boolean).map(t => String(t).toUpperCase());
        return equipmentTerms.some(eTerm =>
            assetTerms.some(aTerm => eTerm.includes(aTerm) || aTerm.includes(eTerm))
        );
    });
    const sources = gatherSourcesForAsset(asset, matched);
    if (matched.length > 0) {
        html += `<div class="detail-section"><h4>Linked Equipment Records</h4>`;
        matched.forEach(e => {
            const hasAttrs = equipAttrs[e.id] && equipAttrs[e.id].length > 0;
            html += `<div class="detail-rel-row">
                <span class="detail-rel-type">${e.mcc || '—'}</span>
                <span class="detail-rel-name equip-tag" onclick="navigateToEquipment(${e.id})">${e.name}</span>
                ${hasAttrs ? '<span class="has-specs">● Has specs</span>' : ''}
            </div>`;
        });
        html += `</div>`;
    }
    html += buildSourceListHtml(sources);
    html += `<div class="detail-section">
        <h4>Verification</h4>
        <p class="detail-note">This view is derived from the site layout register and linked records.</p>
        ${renderFeedbackPanel({
            item_type: 'asset',
            item_id: asset.id,
            item_label: asset.name,
            response_text: `${asset.name} in ${activeLocation.name}`,
            sources,
            channel: 'portal',
        })}
    </div>`;
    el('detail-content').innerHTML = html;
    el('equipment-detail-panel').classList.add('panel-open');
    el('detail-overlay').style.display = 'block';
}

// ── Documents ─────────────────────────────────────────────────────────────────
function loadDocuments() {
    const nonElec = DATA_DOCUMENTS.filter(d => !['electrical_drawing','obsolete','photo'].includes(d.category));
    const container = el('docs-list');
    if (!container) return;
    function renderDocs(items) {
        container.innerHTML = items.length === 0
            ? '<p class="card-note">No documents match.</p>'
            : items.map(d => `<div class="drawing-row">
                <div class="drawing-ref">${d.category.replace('_',' ')}</div>
                <div class="drawing-desc">${d.description||d.filename}</div>
                <div class="drawing-mcc">${d.area||'—'}</div>
                <div class="drawing-actions">
                    ${d.pdf_link ? `<a class="drawing-link" href="${d.pdf_link}" target="_blank" rel="noopener">Open source</a>` : ''}
                </div>
                ${renderFeedbackPanel({
                    item_type: 'document',
                    item_id: String(d.id || ''),
                    item_label: d.description || d.filename,
                    source_path: d.file_path,
                    source_link: d.pdf_link,
                    response_text: d.description || d.filename,
                    sources: d.pdf_link ? [{ label: d.description || d.filename, path: d.file_path, link: d.pdf_link }] : [],
                    channel: 'portal',
                }, true)}
              </div>`).join('');
    }
    renderDocs(nonElec);
    el('docs-search')?.addEventListener('input', () => {
        const q = el('docs-search').value.toLowerCase().trim();
        renderDocs(q ? nonElec.filter(d =>
            (d.description||'').toLowerCase().includes(q) ||
            (d.filename   ||'').toLowerCase().includes(q) ||
            (d.category   ||'').toLowerCase().includes(q)
        ) : nonElec);
    });
}

